package io.github.ningpp.compat;

/** Replacement for System.Configuration.SettingsPropertyNotFoundException (generated by CSharpToJava converter). */
public class SettingsPropertyNotFoundException extends RuntimeException {
    private int hresult;
    public SettingsPropertyNotFoundException() { super(); }
    public SettingsPropertyNotFoundException(String message) { super(message); }
    public SettingsPropertyNotFoundException(String message, Throwable cause) { super(message, cause); }

    public int getHResult() { return hresult; }
    public void setHResult(int value) { this.hresult = value; }
}
